import sys

def is_magical(n):
    s = str(n)
    total = 0
    length = len(s)
    for mask in range(1, 1 << length):
        product = 1
        for i in range(length):
            if mask & (1 << i):
                product *= int(s[i])
        total += product
    return total % 2 == 0

def find_kth_magical_number(K):
    if K == 1:
        return 0
